import { z } from "zod";

export const getExpertSchema = (t: (key: string) => string) => z.object({
  email: z.string().min(1, t("experts.edit.form.validation.emailRequired")).email(t("experts.edit.form.validation.invalidEmail")),
  phone_number: z.string().min(1, t("experts.edit.form.validation.phoneRequired")),
  display_name: z.string().min(1, t("experts.edit.form.validation.nameRequired")).max(128, t("experts.edit.form.validation.nameMaxLength")),
  title: z.string().max(128, t("experts.edit.form.validation.titleMaxLength")).optional().or(z.literal("")),
  bio: z.string().optional().or(z.literal("")),
  years_experience: z.number().min(0, t("experts.edit.form.validation.yearsMin")).optional().or(z.literal("")),
  certifications: z.array(
    z.object({
      cert_name: z.string().max(128, t("experts.edit.form.validation.certMaxLength")).optional().or(z.literal(""))
    })
  ).optional(),
  website: z.string().url(t("experts.edit.form.validation.invalidUrl")).max(255).optional().or(z.literal("")),
  linkedin: z.string().url(t("experts.edit.form.validation.invalidUrl")).max(255).optional().or(z.literal("")),
  languages: z.array(z.union([z.string(), z.number()])).min(1, t("experts.edit.form.validation.selectLanguage")),
  categories: z.array(z.number()).min(1, t("experts.edit.form.validation.selectCategory")),
  countries: z.array(z.number()).min(1, t("experts.edit.form.validation.selectCountry")),
  podcast: z.boolean().optional(),
  image: z.any().optional()
});

export type ExpertFormValues = z.infer<ReturnType<typeof getExpertSchema>>;

